# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects an uncompilable static schema when registering its tool', () => {
    const registry = new ToolRegistry();
    let registrationError: unknown;

    try {
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 42,
          },
        },
        async () => 'unreachable'
      );
    } catch (error) {
      registrationError = error;
    }

    expect(registrationError).toEqual(
      expect.objectContaining({message: expect.stringMatching(/broken_weather/), cause: expect.any(Error)})
    );
  });

  it('rejects an input missing a required property before invoking the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('weather', {});

    expect({executorCalls: execute.mock.calls.length, response}).toEqual({
      executorCalls: 0,
      response: {result: expect.stringMatching(/location.*required|required.*location/i)},
    });
  });

  it('logs a schema rejection without the invalid input value', async () => {
    const entries: Array<{message: string; fields?: Record<string, unknown>}> = [];
    const record = (_category: string, message: string, fields?: Record<string, unknown>) => {
      entries.push({message, fields});
    };
    const logger: Logger = {debug: record, info: record, warn: record, error: record};
    setLogger(logger);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => 'sunny'
    );

    await registry.execute('weather', {location: 123456789});

    expect({
      validationEntry: entries.some(
        entry => /validation/i.test(entry.message) && /location.*string/i.test(String(entry.fields?.error))
      ),
      includesInvalidValue: JSON.stringify(entries).includes('123456789'),
    }).toEqual({validationEntry: true, includesInvalidValue: false});
  });

  it('passes valid input and undeclared extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'celsius'};
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async toolInput => {
        executorCalls += 1;
        receivedInput = toolInput;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', input);

    expect({executorCalls, receivedInput, response}).toEqual({
      executorCalls: 1,
      receivedInput: input,
      response: {result: 'sunny'},
    });
  });
});
import Ajv from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ToolValidator;
}

type ToolValidationError = {
  keyword: string;
  params: unknown;
  message?: string;
  instancePath?: string;
  dataPath?: string;
};

type ToolValidator = ((input: Record<string, unknown>) => boolean) & {
  errors?: ToolValidationError[] | null;
};

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({strict: false, validateFormats: false} as never);
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ToolValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const staticValidator = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes known tools; schema rejections are ToolResponses (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = tool.staticValidator ?? this.getDynamicValidator(definition);
    if (!validate(input)) {
      const error = this.formatValidationErrors(validate.errors);
      log.warn('tool', 'input validation failed', {name, error});
      return {result: `Tool input validation failed: ${error}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private compile(definition: ToolDefinition): ToolValidator {
    try {
      return this.validator.compile(definition.inputSchema) as ToolValidator;
    } catch (error) {
      const reason = error instanceof Error ? error.message : 'unknown schema error';
      throw new Error(`Invalid input schema for tool ${definition.name}: ${reason}`, {cause: error});
    }
  }

  private getDynamicValidator(definition: ToolDefinition): ToolValidator {
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) return cached;
    const compiled = this.compile(definition);
    this.dynamicValidators.set(definition.inputSchema, compiled);
    return compiled;
  }

  private formatValidationErrors(errors: ToolValidationError[] | null | undefined): string {
    return (
      errors
        ?.map(error => {
          const missingProperty =
            error.keyword === 'required' ? (error.params as {missingProperty: string}).missingProperty : undefined;
          const instancePath = error.instancePath ?? error.dataPath;
          const path = missingProperty ? `${instancePath ?? ''}/${missingProperty}` : instancePath || '/';
          return `${path} ${error.message ?? 'does not match the tool schema'}`;
        })
        .join('; ') ?? 'input does not match the tool schema'
    );
  }
}
